with department_stats as (select dept_id, min(salary) as min_salary, round((100 * sum(case when job_title = 'Manager' then 1 else 0 end)) / count(*), 1) as pct_manager from employees where full_name like '%Kim%' group by dept_id) select departments.id, departments.dept_name, department_stats.min_salary, department_stats.pct_manager from departments join department_stats on departments.id = department_stats.dept_id where department_stats.pct_manager >= 71;
